 CREATE PROCEDURE [organizations].[GETALLCOUNTRYBYORGID]
	(
		@OrgId int
	)
AS
BEGIN
DECLARE @OrgCountrytbl TABLE(Id int);
DECLARE @Countries nvarchar(50);
SET @Countries =  (select CountryId from [organizations].[Organizations] where id= @OrgId)

INSERT INTO @OrgCountrytbl (Id)
   SELECT value from string_split(@Countries,',')

	SELECT c.Id
          ,c.CountryName
          ,c.CountryCode
          ,c.CountryCodeNumber
          ,c.FinancialStartDate
          ,c.FinancialEndDate
          ,c.CreatedOn
          ,c.CreatedBy
          ,c.ModifiedBy
          ,c.ModifiedOn
          ,c.UID
	FROM [product_owner].[Country] c inner join
	@OrgCountrytbl org on org.Id = c.Id
   where c.[Status] = 1
	
END;
GO
