CREATE PROCEDURE [organizations].[USP_GETALLORGANIZATION]  
    @userId INT = NULL  
AS  
BEGIN  
    SET NOCOUNT ON;  
  
    -- Temporary table to hold intermediate results  
    DECLARE @managerId INT;  
  
    -- Check if @userId equals ManagerId in any record  
    SELECT TOP 1 @managerId = ManagerId  
    FROM [organizations].[Organizations]  
    WHERE ManagerId = @userId;  
  
    IF @managerId IS NOT NULL  
    BEGIN  
 PRINT @managerId  
        -- If @userId equals ManagerId, return all organizations where ManagerId = @userId and StatusId = 2  
        SELECT org.[Id],  
               org.[OrganizationName],  
               org.[CountryId],  
               org.[StateId],  
      s.[StateName],  
               org.[City],  
               org.[Address],  
               org.[Pin],  
               org.[TypeOfProduct],  
               org.[NumberOfEntities],  
               org.[NumberOfUsers],  
               org.[CreatedOn],  
               org.[CreatedBy],  
               org.[ModifiedOn],  
               org.[ModifiedBy],  
               org.[UUID],  
               org.[Status],  
               org.[EntityTypeId],  
               org.[MajorIndustryId],  
               org.[MinorIndustryId],  
               org.[BillingLevelId],  
               org.[ManagerId],  
               org.[CountryDDId],  
               org.[PrimaryEntity],
			   org.[FullName],
			   org.[Designation],
			   org.[EmailID],
			   org.[Password]
        FROM [organizations].[Organizations] AS org  
  LEFT JOIN [product_owner].[State] AS s ON org.[StateId] = s.[Id]   
        WHERE org.[ManagerId] = @userId AND org.[Status] = 2  
        UNION  
        SELECT org.[Id],  
               org.[OrganizationName],  
               org.[CountryId],  
               org.[StateId],  
      s.[StateName],  
               org.[City],  
               org.[Address],  
               org.[Pin],  
               org.[TypeOfProduct],  
               org.[NumberOfEntities],  
               org.[NumberOfUsers],  
               org.[CreatedOn],  
               org.[CreatedBy],  
               org.[ModifiedOn],  
               org.[ModifiedBy],  
               org.[UUID],  
               org.[Status],  
               org.[EntityTypeId],  
               org.[MajorIndustryId],  
               org.[MinorIndustryId],  
               org.[BillingLevelId],  
               org.[ManagerId],  
               org.[CountryDDId],  
               org.[PrimaryEntity],
			   org.[FullName],
			   org.[Designation],
			   org.[EmailID],
			   org.[Password]
        FROM [organizations].[Organizations] AS org  
  LEFT JOIN [product_owner].[State] AS s ON org.[StateId] = s.[Id]   
        WHERE org.[CreatedBy] = @userId AND org.[Status] = 2;  
    END  
    ELSE  
    BEGIN  
        -- If @userId does not equal ManagerId, find the ManagerId where CreatedBy = @userId  
        SELECT TOP 1 @managerId = ManagerId  
        FROM [organizations].[Organizations] AS org  
        WHERE CreatedBy = @userId;  
  
  --DECLARE @UserIds TABLE (Id INT);  
  --INSERT INTO @UserIds (Id)  
  --      SELECT usr.Id  
  --      FROM [dbo].[Users] AS usr  
  --      WHERE usr.ManagerId = @managerId;  
  
  
  PRINT 'INSIDE ELSE'   
  PRINT @managerId  
  --SELECT * FROM @UserIds  
  
        -- Return all organizations where ManagerId = found ManagerId  
        SELECT org.[Id],  
               org.[OrganizationName],  
               org.[CountryId],  
               org.[StateId],  
      s.[StateName],  
               org.[City],  
               org.[Address],  
               org.[Pin],  
               org.[TypeOfProduct],  
               org.[NumberOfEntities],  
               org.[NumberOfUsers],  
               org.[CreatedOn],  
               org.[CreatedBy],  
               org.[ModifiedOn],  
               org.[ModifiedBy],  
               org.[UUID],  
               org.[Status],  
               org.[EntityTypeId],  
               org.[MajorIndustryId],  
               org.[MinorIndustryId],  
               org.[BillingLevelId],  
               org.[ManagerId],  
               org.[CountryDDId],  
               org.[PrimaryEntity],
			   org.[FullName],
			   org.[Designation],
			   org.[EmailID],
			   org.[Password]
        FROM [organizations].[Organizations] AS org  
  LEFT JOIN [product_owner].[State] AS s ON org.[StateId] = s.[Id]   
        --WHERE (org.[ManagerId] = @managerId  OR org.[CreatedBy] IN (SELECT Id FROM @UserIds)) AND org.[Status] = 2;  
        WHERE (org.[ManagerId] = @managerId  OR org.[CreatedBy] = @managerId) AND org.[Status] = 2;  
    
 END  
END;  
GO
