/****** Object:  StoredProcedure [organizations].[USP_GETBILLINGDETAILSVIEW]    Script Date: 9/6/2024 2:11:22 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [organizations].[USP_GETBILLINGDETAILSVIEW]
	-- Add the parameters for the stored procedure here
	@Id BigInt,
	@OrganizationId BigInt
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here
	Select b.*,
			o.OrganizationName,
			e.EntityName,
			c.[CountryName],
			s.StateName,
			sp.[ServiceProviderName],
			bf.[Frequency],
			CONVERT(NVARCHAR, b.BillDate, 106) AS BillDateString,
			CONVERT(NVARCHAR, b.CollectionDate, 106) AS CollectionDateString,
			bs.BillStatusName,
			ds.DeliveryStatusName,
			pt.[TypeOfProduct],
			bl.[BillingLevelName]
		From 
			[organizations].[BillingDetails] b
			Inner Join [organizations].[Organizations] o On o.Id = b.OrganizationId
			Left Join [organizations].[Entity] e On e.Id = b.EntityId
			Left Join [product_owner].[Country] c On c.Id = b.CountryId
			Left Join [product_owner].[State] s On s.Id = b.StateId
			Left Join [organizations].[ServiceProvider] sp On sp.Id = b.ServiceProvider
			Left Join [organizations].[BillingFrequency] bf On bf.Id = b.BillingFrequency
			Left Join [organizations].[BillStatus] bs On bs.Id = b.BillStatus
			Left Join [organizations].[DeliveryStatus] ds On ds.Id = b.DeliveryStatus
			Left Join [organizations].[ProductType] pt On pt.Id = o.[TypeOfProduct]
			Left Join [organizations].[BillingLevel] bl On bl.Id = o.[BillingLevelId]
		Where 
			b.Id = Case When @Id > 0 Then @Id Else b.Id End
			And o.Id = Case When @OrganizationId > 0 Then @OrganizationId Else o.Id End
			And b.Status = Case When @OrganizationId > 0 Then 2 Else b.Status End
			And 1 = case when @Id > 0 Or @OrganizationId > 0 Then 1 Else 2 End -- This is added for orgid/billing id is not there
		Order By
			b.Id Desc
END
GO
