/****** Object:  StoredProcedure [organizations].[USP_GETENTITYAPPROVALLIST]    Script Date: 9/6/2024 2:11:22 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

CREATE Procedure [organizations].[USP_GETENTITYAPPROVALLIST]
(
		@UserUID UniqueIdentifier
)
AS
BEGIN

SELECT ROW_NUMBER() OVER (ORDER BY e.Id) AS SNo,
e.Id as EntityId, 'Entity' as [Type] , e.EntityName , u.EmpId as CustomerId,
u.FullName as PointOfContact, M.FullName as Approvedby, 
 'Add Entity' as OnboardingStage,
 CASE WHEN e.[Status] = 1 THEN 'Pending' 
            WHEN e.[Status] = 2 THEN 'Approved' 
			WHEN e.[Status] = 3 THEN 'Rejected'
			WHEN e.[Status] = 4 THEN 'Reviewed'
			WHEN e.[Status] = 5 THEN 'Forwarded'
			WHEN e.[Status] = 0 THEN 'Unknown'
            ELSE ''
       END AS [Status]

FROM [ComplianceNew].organizations.Entity AS e 
inner join [ComplianceNew].[dbo].[Users] u on u.[uid] = e.[uid]
inner JOIN [ComplianceNew].[dbo].Users M ON M.Id = e.ManagerId
Where e.[UID] = @UserUID
END
GO
