CREATE PROCEDURE [organizations].[USP_GETENTITYDETAILS] 
(
	@EntityId int
)
AS
BEGIN

    SELECT e.*, o.OrganizationName as OrganizationName, u.FullName as PointOfContact , m.FullName as Approvedby 
	FROM [ComplianceNew].organizations.Entity AS e 
	inner join [ComplianceNew].[organizations].[organizations] o on o.Id = e.OrganizationId
inner join [ComplianceNew].[dbo].[Users] u on u.Id = e.CreatedBy
Left outer join [ComplianceNew].[dbo].[Users] m on m.Id = e.ManagerId
WHERE  e.Id = @EntityId

END;
