/****** Object:  StoredProcedure [organizations].[USP_GETENTITYVIEWDETAILS]    Script Date: 9/6/2024 2:11:22 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE PROCEDURE [organizations].[USP_GETENTITYVIEWDETAILS] 
(
	@EntityId int
)
AS
BEGIN

    SELECT c.[CountryName],et.[EntityType], s.[StateName] ,mii.[MinorIndustryName], mi.[MajorIndustryName], e.*, u.EmpId as CustomerId, u.FullName as PointOfContact , 
	CASE WHEN m.FullName IS NULL THEN 'N/A' ELSE m.FullName END as Approvedby 
	FROM [ComplianceNew].organizations.Entity AS e 
inner join [ComplianceNew].[dbo].[Users] u on u.id = e.CreatedBy
LEFT OUTER JOIN [product_owner].[Country] c on c.Id = e.countryId
LEFT OUTER JOIN [product_owner].[State] s on s.Id = e.stateId
LEFT OUTER JOIN [product_owner].[CountryEntityTypeMapping] cet on cet.Id = e.EntityTypeId
LEFT OUTER JOIN [product_owner].[EntityType] et on et.Id = cet.EntityTypeId
LEFT OUTER JOIN [product_owner].[MajorIndustry] mi on mi.Id = e.MajorIndustryId
LEFT OUTER JOIN [product_owner].[MinorIndustry] mii on mii.Id = e.MinorIndustryId
LEFT OUTER JOIN [ComplianceNew].[dbo].[Users] m on m.Id = e.ManagerId
WHERE  e.Id = @EntityId;

END;
GO
/****** Object:  StoredProcedure [organizations].[USP_GETORGANIZATIONANDENTITYAPPROVALLIST]    Script Date: 9/6/2024 2:11:22 PM ******/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO

 CREATE procedure [organizations].[USP_GETORGANIZATIONANDENTITYAPPROVALLIST]
(
		@UserUID int
)
AS
BEGIN
	
SELECT 
		OH.Id As OrganizationId, 
		NULL as EntityId,
		Null As BillingDetilsId,
		'Organization' AS [Type],
		OH.OrganizationName as [Name],
		U.EmpId as CustomerId,
		UK.FullName as PointOfContact, 
		OA.ApprovalStatus AS StatusId,
		RAS.[Status],
		'Add Organization' as OnboardingStage,
		OA.CreatedBy, 
		OH.CreatedOn,
		OA.[UID],
		U.FullName AS Approvedby
		--CASE WHEN RAS.Status = 'Approved' THEN U.FullName ELSE 'N/A' END AS Approvedby
	FROM 
		[organizations].OrganizationApproval OA
	INNER JOIN 
		[dbo].Users U ON U.Id = OA.ManagerId
	INNER JOIN 
		[dbo].Users UK ON UK.Id = OA.CreatedBy
	INNER JOIN 
		[dbo].RefApprovalStatus RAS ON RAS.Id = OA.ApprovalStatus
	INNER JOIN 
		[organizations].OrganizationHistory OH ON OH.HistoryId = OA.Id
	WHERE 
		OA.ManagerId =  @UserUID 
		OR OA.CreatedBy =  @UserUID

UNION
SELECT
EH.OrganizationId, 
		EH.Id as EntityId,
		Null As BillingDetilsId,
		'Entity' AS [Type],
		EH.EntityName as [Name],
		U.EmpId as CustomerId,
		UK.FullName as PointOfContact, 
		EA.ApprovalStatus AS StatusId,
		RAS.[Status],
		'Add Entity' as OnboardingStage,
		EA.CreatedBy, 
		EH.CreatedOn,
		EA.[UID],
		CASE WHEN RAS.Status = 'Approved' THEN U.FullName ELSE 'N/A' END AS Approvedby
	FROM 
		[organizations].EntityApproval EA
	INNER JOIN 
		[dbo].Users U ON U.Id = EA.ManagerId
	INNER JOIN 
		[dbo].Users UK ON UK.Id = EA.CreatedBy
	INNER JOIN 
		[dbo].RefApprovalStatus RAS ON RAS.Id = EA.ApprovalStatus
	INNER JOIN 
		[organizations].EntityHistory EH ON EH.HistoryId = EA.EntityId
	WHERE 
		EA.ManagerId = @UserUID 
		OR EA.CreatedBy = @UserUID

UNION
SELECT
		BH.OrganizationId, 
		Null as EntityId,
		BH.Id As BillingDetilsId,
		'Billing Details' AS [Type],
		IsNull(e.[EntityName],o.OrganizationName) as [Name],
		U.EmpId as CustomerId,
		UK.FullName as PointOfContact, 
		BA.ApprovalStatus AS StatusId,
		RAS.[Status],
		'Add Billing Details' as OnboardingStage,
		BA.CreatedBy, 
		BA.CreatedOn,
		BA.[UID],
		CASE WHEN RAS.Status = 'Approved' THEN U.FullName ELSE 'N/A' END AS Approvedby
	FROM 
		[organizations].[BillingDetailsApproval] BA
	INNER JOIN 
		[dbo].Users U ON U.Id = BA.ManagerId
	INNER JOIN 
		[dbo].Users UK ON UK.Id = BA.CreatedBy
	INNER JOIN 
		[dbo].RefApprovalStatus RAS ON RAS.Id = BA.ApprovalStatus
	INNER JOIN 
		[organizations].[BillingDetailsHistory] BH ON BH.Id = BA.[BillingDetailId]
	INNER JOIN 
		[organizations].[Organizations] o On o.Id = BH.OrganizationId
	LEFT JOIN
		[organizations].[Entity] e On e.Id = BH.EntityId
	WHERE 
		BA.ManagerId = @UserUID 
		OR BA.CreatedBy = @UserUID

Order by OH.CreatedOn desc, OH.Id desc , EntityId
END
GO
