CREATE PROCEDURE [organizations].[USP_GETORGANIZATIONAPPROVALLIST]
	(
		@UserUID NVARCHAR(100)
	)
AS
BEGIN
	DECLARE @UserId INT;

	SELECT @UserId = ID FROM Users WHERE UID = @UserUID

	SELECT 
		OA.Id as OrganizationId, 
		OH.OrganizationName as OrganizationName,
		UK.FullName, 
		OA.ApprovalStatus AS StatusId,
		RAS.Status,
		OA.CreatedBy, 
		'Organization' AS Type,
		OA.UID,
		CASE WHEN RAS.Status = 'Approved' THEN U.FullName ELSE '' END AS ApprovedBy
	FROM 
		[organizations].OrganizationApproval OA
	--INNER JOIN 
	--	[organizations].OrganizationApproval OA ON OA.OrganizationId = O.Id
	INNER JOIN 
		[dbo].Users U ON U.Id = OA.ManagerId
	INNER JOIN 
		[dbo].Users UK ON UK.Id = OA.CreatedBy
	INNER JOIN 
		[dbo].RefApprovalStatus RAS ON RAS.Id = OA.ApprovalStatus
	INNER JOIN 
		[organizations].OrganizationHistory OH ON OH.HistoryId = OA.Id
	WHERE 
		OA.ManagerId = @UserId OR OA.CreatedBy = @UserId
END
