CREATE PROCEDURE [organizations].[USP_POSTBILLINGDETAILS]
	@Id BigInt,
	@OrganizationId BigInt,
	@EntityId BigInt,
	@PAN NVarChar(50),
	@TAN NVarChar(50),
	@GSTNo NVarChar(50),
	@Address NVarChar(Max),
	@City NVarChar(200),
	@CountryId Int,
	@StateId Int,
	@PIN VarChar(10),
	@OrderId NVarChar(100),
	@ServiceProvider Int,
	@FeePerEntity Int,
	@FeePerUser Int,
	@BillNumber NVarChar(100),
	@BillingFrequency Int,
	@BillDate DateTime,
	@Remarks NVarChar(Max),
	@CollectionDate DateTime,
	@BillAmount Int,
	@TDS Decimal(6,2),
	@ReceivedAmount Int,
	@CheckNumber NVarChar(100),
	@BillStatus Int,
	@DeliveryStatus Int,
	@CreatedBy BigInt,
	@TotalFee Int
AS
BEGIN
	-- SET NOCOUNT ON added to prevent extra result sets from
	-- interfering with SELECT statements.
	SET NOCOUNT ON;

    -- Insert statements for procedure here

	Declare @BillingDetailId BigInt, @ManagerId BigInt, @StatusId Int
	Select @ManagerId = ManagerId From [dbo].[Users] Where Id = @CreatedBy
	Set @StatusId = Case When @ManagerId Is Null Then 2 Else 1 End
	Insert Into [organizations].[BillingDetails]([OrganizationId],[PAN],[TAN],[GSTNo],[Address],[City],[CountryId],[StateId],
			[PIN],[OrderId],[ServiceProvider],[FeePerEntity],[FeePerUser],[BillNumber],[BillingFrequency],[BillDate],
			[Remarks],[CollectionDate],[BillAmount],[TDS],[ReceivedAmount],[CheckNumber],[BillStatus],[DeliveryStatus],
			[CreatedOn],[CreatedBy],[Status],[EntityId],TotalFee)
	Values (@OrganizationId,@PAN,@TAN,@GSTNo,@Address,@City,@CountryId,@StateId,
			@PIN,@OrderId,@ServiceProvider,@FeePerEntity,@FeePerUser,@BillNumber,@BillingFrequency,@BillDate,
			@Remarks,@CollectionDate,@BillAmount,@TDS,@ReceivedAmount,@CheckNumber,@BillStatus,@DeliveryStatus,
			GetDate(),@CreatedBy,@StatusId,@EntityId,@TotalFee)

	SET @BillingDetailId = Scope_Identity();

	Insert Into [organizations].[BillingDetailsHistory](Id,[OrganizationId],[PAN],[TAN],[GSTNo],[Address],[City],[CountryId],[StateId],
			[PIN],[OrderId],[ServiceProvider],[FeePerEntity],[FeePerUser],[BillNumber],[BillingFrequency],[BillDate],
			[Remarks],[CollectionDate],[BillAmount],[TDS],[ReceivedAmount],[CheckNumber],[BillStatus],[DeliveryStatus],
			[CreatedOn],[CreatedBy],[Status],[EntityId],TotalFee)
	Values (@BillingDetailId,@OrganizationId,@PAN,@TAN,@GSTNo,@Address,@City,@CountryId,@StateId,
			@PIN,@OrderId,@ServiceProvider,@FeePerEntity,@FeePerUser,@BillNumber,@BillingFrequency,@BillDate,
			@Remarks,@CollectionDate,@BillAmount,@TDS,@ReceivedAmount,@CheckNumber,@BillStatus,@DeliveryStatus,
			GetDate(),@CreatedBy,@StatusId,@EntityId,@TotalFee)

	Insert Into [organizations].[BillingDetailsApproval]([BillingDetailId],[ManagerId],[ApprovalStatus],[CreatedOn],[CreatedBy])
	Values (@BillingDetailId,IsNull(@ManagerId,0),@StatusId,GetDate(),@CreatedBy)

END
GO
