CREATE PROCEDURE [organizations].[USP_POSTORGANIZATION] 
(
    @Id BIGINT = 0,
    @OrganizationName NVARCHAR(100) = NULL,
    @CountryId NVARCHAR(100) = NULL,
    @StateId BIGINT = NULL,
    @City NVARCHAR(100) = NULL,
    @Address NVARCHAR(100) = NULL,
    @Pin NVARCHAR(20) = NULL,
    @TypeOfProduct NVARCHAR(50) = NULL,
    @NumberOfEntities INT = NULL,
    @NumberOfUsers INT = NULL,
    @EntityTypeId INT = NULL,
    @MajorIndustryId INT = NULL,
    @MinorIndustryId INT = NULL,
    @BillingLevelId INT = NULL,
	@Status INT = NULL,
    @CreatedBy BIGINT = 0,
    @ModifiedBy BIGINT = 0,
    @UUID UNIQUEIDENTIFIER = NULL,
	@PrimaryEntity NVARCHAR(100) = NULL
)
AS
BEGIN
    IF EXISTS(SELECT * FROM organizations.Organizations WHERE OrganizationName = @OrganizationName)
    BEGIN
        SELECT Id,
               OrganizationName,
               CountryId,
               StateId,
               City,
               Address,
               Pin,
               TypeOfProduct,
               NumberOfEntities,
               NumberOfUsers,
               EntityTypeId,
               MajorIndustryId,
               MinorIndustryId,
               BillingLevelId,
			   Status,
               CreatedOn,
               CreatedBy,
               ModifiedOn,
               ModifiedBy,
               UUID,
			   PrimaryEntity,
               0 AS ResponseCode, 'Organization already exists' AS ResponseMessage
        FROM organizations.Organizations
        WHERE OrganizationName = @OrganizationName;
        
        RETURN;
    END;

    IF(@Id = 0 OR @Id IS NULL)
    BEGIN
        INSERT INTO organizations.Organizations
        (
            OrganizationName, CountryId, StateId, City, Address, Pin, 
            TypeOfProduct, NumberOfEntities, NumberOfUsers, EntityTypeId, MajorIndustryId, MinorIndustryId, BillingLevelId, Status, CreatedOn, CreatedBy, UUID, PrimaryEntity
        )
        VALUES
        (
            @OrganizationName, @CountryId, @StateId, @City, @Address, @Pin, 
            @TypeOfProduct, @NumberOfEntities, @NumberOfUsers, @EntityTypeId, @MajorIndustryId, @MinorIndustryId, @BillingLevelId, @Status, GETDATE(), @CreatedBy, NEWID(), @PrimaryEntity
        );

        SELECT @Id = SCOPE_IDENTITY();
    END;
    ELSE
    BEGIN
        UPDATE organizations.Organizations
        SET 
            OrganizationName = @OrganizationName,
            CountryId = @CountryId,
            StateId = @StateId,
            City = @City,
            Address = @Address,
            Pin = @Pin,
            TypeOfProduct = @TypeOfProduct,
            NumberOfEntities = @NumberOfEntities,
            NumberOfUsers = @NumberOfUsers,
            EntityTypeId = @EntityTypeId,
            MajorIndustryId = @MajorIndustryId,
            MinorIndustryId = @MinorIndustryId,
            BillingLevelId = @BillingLevelId,
			Status = @Status,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE(),
			PrimaryEntity = @PrimaryEntity
        WHERE UUID = @UUID;
    END;

    SELECT Id,
           OrganizationName,
           CountryId,
           StateId,
           City,
           Address,
           Pin,
           TypeOfProduct,
           NumberOfEntities,
           NumberOfUsers,
           EntityTypeId,
           MajorIndustryId,
           MinorIndustryId,
           BillingLevelId,
		   Status,
           CreatedOn,
           CreatedBy,
           ModifiedOn,
           ModifiedBy,
           UUID,
		   PrimaryEntity,
           1 AS ResponseCode, 'Organization Added/Updated Successfully' AS ResponseMessage
    FROM organizations.Organizations
    WHERE Id = @Id;
END;
GO
