    @Organizations BIGINT,
    @ProductOrderBasicDetail BIGINT,
    @Pan NVARCHAR(50),
    @Tan NVARCHAR(50),
    @GstNumber NVARCHAR(50),
    @OrderId NVARCHAR(50),
    @ProductType INT,
    @AppServiceProvider INT,
    @FeePerUser INT,
    @FeePerEntity INT,
    @CreatedBy BIGINT
AS
BEGIN
    SET NOCOUNT ON;

    -- Check if the record already exists
    IF EXISTS (SELECT 1 FROM [organizations].[ProductOrder] WHERE [Id] = @Id)
    BEGIN
        -- Update the existing record
        UPDATE [organizations].[ProductOrder]
        SET [Organizations] = @Organizations,
            [ProductOrderBasicDetail] = @ProductOrderBasicDetail,
            [Pan] = @Pan,
            [Tan] = @Tan,
            [GstNumber] = @GstNumber,
            [OrederId] = @OrderId,
            [ProductType] = @ProductType,
            [AppServiceProvider] = @AppServiceProvider,
            [FeePerUser] = @FeePerUser,
            [FeePerEntity] = @FeePerEntity,
            [ModifiedBy] = @CreatedBy,
            [ModifiedOn] = GETDATE()
        WHERE [Id] = @Id;
    END
    ELSE
    BEGIN
        -- Insert a new record
        INSERT INTO [organizations].[ProductOrder] ([Organizations], [ProductOrderBasicDetail], [Pan], [Tan], [GstNumber],
            [OrederId], [ProductType], [AppServiceProvider], [FeePerUser], [FeePerEntity], [CreatedOn], [CreatedBy], [ModifiedBy], [ModifiedOn])
        VALUES (@Organizations, @ProductOrderBasicDetail, @Pan, @Tan, @GstNumber,
                @OrderId, @ProductType, @AppServiceProvider, @FeePerUser, @FeePerEntity, GETDATE(), @CreatedBy, @CreatedBy, GETDATE());
     SELECT @Id = SCOPE_IDENTITY() ;
	END

	SELECT 
		[Id], 
		[Organizations], 
		[ProductOrderBasicDetail], 
		[Pan], 
		[Tan], 
		[GstNumber], 
		[OrederId], 
		[ProductType], 
		[AppServiceProvider], 
		[FeePerUser], 
		[FeePerEntity], 
		[CreatedOn], 
		[CreatedBy], 
		[ModifiedBy], 
		[ModifiedOn], 
		[UID]
	FROM 
		[organizations].[ProductOrder]
	WHERE 
		[Id] =  @Id;

END;
