CREATE PROCEDURE [organizations].[USP_UPDATEBILLINGDETAILAPPROVAL]
    (
        @BillingDetailId INT = 0,
        @ManagerId INT = 0,
        @ApprovalStatus VARCHAR(20) = '',
        @CreatedBy INT = 0
    )
AS
BEGIN

    DECLARE @ISAdmin BIT = 0;
    DECLARE @ApprovalStatusId INT = 0, @APPROVEDSTATUS INT = 0, @REVIEWEERSTATUS INT = 0, @PENDINGAPPROVAL INT = 0, @FORWARD INT = 0, @NEWMANAGERID INT = 0;

    SELECT @APPROVEDSTATUS = Id FROM RefApprovalStatus WHERE Status='Approved';
    SELECT @REVIEWEERSTATUS = Id FROM RefApprovalStatus WHERE Status='Reviewed';
    SELECT @PENDINGAPPROVAL = Id FROM RefApprovalStatus WHERE Status='Pending';
    SELECT @FORWARD = Id FROM RefApprovalStatus WHERE Status='Forward';

    SELECT @ApprovalStatusId = Id FROM RefApprovalStatus WHERE Status = @ApprovalStatus;

    IF ([dbo].IsSuperAdmin(@CreatedBy) = 1)
    BEGIN
        SET @ISAdmin = 1;

        IF (@ApprovalStatusId = @APPROVEDSTATUS OR @ApprovalStatusId = @PENDINGAPPROVAL)
        BEGIN
            SET @ApprovalStatusId = @APPROVEDSTATUS;
        END;
    END;

    SET @NEWMANAGERID = ISNULL(@ManagerId, 0);

   BEGIN
        UPDATE [organizations].[BillingDetailsApproval]
        SET ApprovalStatus = @ApprovalStatusId,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE [BillingDetailId] = @BillingDetailId
    END;

    BEGIN
        UPDATE [organizations].[BillingDetails]
        SET Status =  @ApprovalStatusId,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE ID = @BillingDetailId;

        UPDATE [organizations].[BillingDetailsHistory]
		SET Status = @ApprovalStatusId,
			ModifiedBy = @CreatedBy,
			ModifiedOn = GETDATE()
		WHERE [Id] = @BillingDetailId;
	END

END;
GO
