CREATE PROCEDURE [organizations].[USP_UPDATEORGANIZATIONAPPROVAL]
    (
        @OrganizationId INT = 0,
        @ManagerId INT = 0,
        @ApprovalStatus VARCHAR(20) = '',
        @CreatedBy INT = 0,
        @UID NVARCHAR(100) = NULL
    )
AS
BEGIN

    DECLARE @ISAdmin BIT = 0;DECLARE @EntityId BigInt, @OrganizationHistoryId BigInt
    DECLARE @ApprovalStatusId INT = 0, @APPROVEDSTATUS INT = 0, @REVIEWEERSTATUS INT = 0, @PENDINGAPPROVAL INT = 0, @FORWARD INT = 0, @NEWMANAGERID INT = 0;

    SELECT @APPROVEDSTATUS = Id FROM RefApprovalStatus WHERE Status='Approved';
    SELECT @REVIEWEERSTATUS = Id FROM RefApprovalStatus WHERE Status='Reviewed';
    SELECT @PENDINGAPPROVAL = Id FROM RefApprovalStatus WHERE Status='Pending';
    SELECT @FORWARD = Id FROM RefApprovalStatus WHERE Status='Forward';

    SELECT @ApprovalStatusId = Id FROM RefApprovalStatus WHERE Status = @ApprovalStatus;

    IF ([dbo].IsSuperAdmin(@CreatedBy) = 1)
    BEGIN
        SET @ISAdmin = 1;

        IF (@ApprovalStatusId = @APPROVEDSTATUS OR @ApprovalStatusId = @PENDINGAPPROVAL)
        BEGIN
            SET @ApprovalStatusId = @APPROVEDSTATUS;
        END;
    END;

    SET @NEWMANAGERID = ISNULL(@ManagerId, 0);

    BEGIN
        UPDATE [organizations].OrganizationApproval 
        SET ApprovalStatus = @ApprovalStatusId,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE UID = @UID;
    END;
	SELECT @OrganizationHistoryId = OrganizationId FROM organizations.OrganizationApproval WHERE UID = @UID
	SELECT @OrganizationId = [Id] FROM [organizations].[OrganizationHistory] WHERE [HistoryId] = @OrganizationHistoryId
	SELECT Top 1 @EntityId = [Id] From [organizations].[Entity] Where [OrganizationId] = @OrganizationId
    BEGIN
        UPDATE [organizations].Organizations 
        SET Status = 1,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE ID = @OrganizationId;

        UPDATE [organizations].[Entity]
        SET Status = 1,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE ID = @EntityId;
    END;

	-- Update Organizations table based on approval status
    --IF (@ApprovalStatusId = @APPROVEDSTATUS OR @ISAdmin = 1)
    BEGIN
        UPDATE [organizations].Organizations 
        SET Status =  @ApprovalStatusId,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE ID = @OrganizationId;

    -- Update OrganizationHistory table
        UPDATE [organizations].OrganizationHistory
		SET Status = @ApprovalStatusId,
			ModifiedBy = @CreatedBy,
			ModifiedOn = GETDATE()
		WHERE HistoryId = @OrganizationId;

		-- Update entity table
        UPDATE  [organizations].[Entity]
        SET Status =  @ApprovalStatusId,
            ModifiedBy = @CreatedBy,
            ModifiedOn = GETDATE()
        WHERE ID = @EntityId;

    -- Update EntityHistory table
        UPDATE [organizations].[EntityHistory]
		SET Status = @ApprovalStatusId,
			ModifiedBy = @CreatedBy,
			ModifiedOn = GETDATE()
		WHERE [Id] = @EntityId;
	END

END;
