CREATE PROCEDURE [organizations].[USP_UPSERTBILLINGDETAILSBASICDETAILHISTORY]
    @Id BIGINT = NULL,
    @Organizations BIGINT,
	@OrganizationsEntityType BIGINT, 
    @Pan VARCHAR(50) = NULL,
    @Tan VARCHAR(50) = NULL,
    @GstNumber VARCHAR(50) = NULL,
    @City INT = NULL,
    @State INT = NULL,
    @Country INT = NULL,
    @Address VARCHAR(255) = NULL,
    @Pin VARCHAR(20) = NULL,
    @CreatedOn DATETIME = NULL,
    @CreatedBy BIGINT,
    @ModifiedBy BIGINT,
    @ModifiedOn DATETIME = NULL,
    @UID UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

	SET @CreatedOn = ISNULL(@CreatedOn, GETDATE());
    SET @ModifiedOn = ISNULL(@ModifiedOn, GETDATE());

    -- Upsert logic
    IF EXISTS (SELECT 1 FROM Organizations.BillingDetailsBasicDetailHistory WHERE Id = @Id)
    BEGIN
        -- Update existing row
        UPDATE Organizations.BillingDetailsBasicDetailHistory
        SET 
            Organizations = @Organizations,
			OrganizationsEntityType = @OrganizationsEntityType,
            Pan = @Pan,
            Tan = @Tan,
            GstNumber = @GstNumber,
            City = @City,
            State = @State,
            Country = @Country,
            Address = @Address,
            Pin = @Pin,
            CreatedOn = @CreatedOn,
            CreatedBy = @CreatedBy,
            ModifiedBy = @ModifiedBy,
            ModifiedOn = @ModifiedOn
        WHERE Id = @Id;
    END
    ELSE
    BEGIN
        -- Insert new row
        INSERT INTO Organizations.BillingDetailsBasicDetailHistory (
            Organizations, OrganizationsEntityType, Pan, Tan, GstNumber, City, State, Country, Address, Pin, CreatedOn, CreatedBy, ModifiedBy, ModifiedOn, UID
        )
        VALUES (
            @Organizations,@OrganizationsEntityType, @Pan, @Tan, @GstNumber, @City, @State, @Country, @Address, @Pin, @CreatedOn, @CreatedBy, @ModifiedBy, @ModifiedOn, NEWID()
        );

        -- Get the Id of the newly inserted row
        SET @Id = SCOPE_IDENTITY();
    END

    -- Return the upserted row
    SELECT * FROM Organizations.BillingDetailsBasicDetailHistory WHERE Id = @Id;
END
GO
