CREATE PROCEDURE [organizations].[USP_UPSERTBILLINGDETAILSBILLINGHISTORY]
(
    @Id INT = NULL,
    @BillingDetailsBasicDetailHistory BIGINT = NULL,
    @BillingDetailsOrderHistory BIGINT = NULL,
    @ProductType INT = NULL,
    @NumberOfEntities INT = NULL,
