    @UID UNIQUEIDENTIFIER = NULL
)
AS
BEGIN
    SET NOCOUNT ON; -- Place NOCOUNT ON at the beginning of the procedure

    -- If Id is provided, try to update the existing record
    IF EXISTS (SELECT 1 FROM Organizations.BillingDetailsBillingHistory WHERE Id = @Id)
    BEGIN
        UPDATE Organizations.BillingDetailsBillingHistory
        SET 
            BillingDetailsBasicDetailHistory = @BillingDetailsBasicDetailHistory,
            BillingDetailsOrderHistory = @BillingDetailsOrderHistory,
            ProductType = @ProductType,
            NumberOfEntities = @NumberOfEntities,
            NumberOfUser = @NumberOfUser,
            ApplicationServiceProvide = @ApplicationServiceProvide,
            FeePerUser = @FeePerUser,
            FeePerEntity = @FeePerEntity,
            BillDate = @BillDate,
            BillingFrequency = @BillingFrequency,
            Remark = @Remark,
            CreatedOn = @CreatedOn,
            CreatedBy = @CreatedBy,
            ModifiedBy = @ModifiedBy,
            ModifiedOn = @ModifiedOn,
            UID = ISNULL(@UID, UID)
        WHERE Id = @Id;
    END
    ELSE
    BEGIN
        -- Insert a new record
        INSERT INTO Organizations.BillingDetailsBillingHistory
        (
            BillingDetailsBasicDetailHistory,
            BillingDetailsOrderHistory,
            ProductType,
            NumberOfEntities,
            NumberOfUser,
            ApplicationServiceProvide,
            FeePerUser,
            FeePerEntity,
            BillDate,
            BillingFrequency,
            Remark,
            CreatedOn,
            CreatedBy,
            ModifiedBy,
            ModifiedOn,
            UID
        )
        VALUES
        (
            @BillingDetailsBasicDetailHistory,
            @BillingDetailsOrderHistory,
            @ProductType,
            @NumberOfEntities,
            @NumberOfUser,
            @ApplicationServiceProvide,
            @FeePerUser,
            @FeePerEntity,
            @BillDate,
            @BillingFrequency,
            @Remark,
            @CreatedOn,
            @CreatedBy,
            @ModifiedBy,
            @ModifiedOn,
            ISNULL(@UID, NEWID())
        );

        -- Get the newly inserted Id
        SET @Id = SCOPE_IDENTITY();
    END

    -- Return the affected row
    SELECT * FROM Organizations.BillingDetailsBillingHistory WHERE Id = @Id;
END;

