    @ModifiedOn DATETIME = NULL,
    @UID UNIQUEIDENTIFIER = NULL
)
AS
BEGIN
    SET NOCOUNT ON;

    -- If Id is provided, try to update the existing record
    IF EXISTS (SELECT 1 FROM Organizations.BillingDetailsCollectionHistory WHERE Id = @Id)
    BEGIN
        UPDATE Organizations.BillingDetailsCollectionHistory
        SET 
            BillingDetailsBasicDetailHistory = @BillingDetailsBasicDetailHistory,
            BillingDetailsOrderHistory = @BillingDetailsOrderHistory,
            BillingDetailsBillingHistory = @BillingDetailsBillingHistory,
            ProductType = @ProductType,
            NumberOfEntities = @NumberOfEntities,
            NumberOfUser = @NumberOfUser,
            ApplicationServiceProvide = @ApplicationServiceProvide,
            CollectionDate = @CollectionDate,
            BillingAmount = @BillingAmount,
            Tds = @Tds,
            ReceivedAmount = @ReceivedAmount,
            NeftCheckNumber = @NeftCheckNumber,
            BillingStatus = @BillingStatus,
            CreatedOn = @CreatedOn,
            CreatedBy = @CreatedBy,
            ModifiedBy = @ModifiedBy,
            ModifiedOn = @ModifiedOn,
            UID = ISNULL(@UID, UID)
        WHERE Id = @Id;
    END
    ELSE
    BEGIN
        -- Insert a new record
        INSERT INTO Organizations.BillingDetailsCollectionHistory
        (
            BillingDetailsBasicDetailHistory,
            BillingDetailsOrderHistory,
            BillingDetailsBillingHistory,
            ProductType,
            NumberOfEntities,
            NumberOfUser,
            ApplicationServiceProvide,
            CollectionDate,
            BillingAmount,
            Tds,
            ReceivedAmount,
            NeftCheckNumber,
            BillingStatus,
            CreatedOn,
            CreatedBy,
            ModifiedBy,
            ModifiedOn,
            UID
        )
        VALUES
        (
            @BillingDetailsBasicDetailHistory,
            @BillingDetailsOrderHistory,
            @BillingDetailsBillingHistory,
            @ProductType,
            @NumberOfEntities,
            @NumberOfUser,
            @ApplicationServiceProvide,
            @CollectionDate,
            @BillingAmount,
            @Tds,
            @ReceivedAmount,
            @NeftCheckNumber,
            @BillingStatus,
            @CreatedOn,
            @CreatedBy,
            @ModifiedBy,
            @ModifiedOn,
            ISNULL(@UID, NEWID())
        );

        -- Get the newly inserted Id
        SET @Id = SCOPE_IDENTITY();
    END

    -- Return the affected row
    SELECT * FROM Organizations.BillingDetailsCollectionHistory WHERE Id = @Id;
END;
GO
