CREATE PROCEDURE [organizations].[USP_UPSERTBILLINGDETAILSORDERHISTORY]
    @Id BIGINT = NULL,
    @Organizations BIGINT,
	@OrganizationsEntityType BIGINT,
    @ProductOrderBasicDetail BIGINT,
    @ProductType INT = NULL,
    @NumberOfEntity INT = NULL,
    @NumberOfUser INT = NULL,
    @AppServiceProvider INT = NULL,
    @OrderId VARCHAR(255) = NULL,
    @FeePerUser INT = NULL,
    @FeePerEntity INT = NULL,
    @CreatedOn DATETIME = NULL,
    @CreatedBy BIGINT,
    @ModifiedBy BIGINT,
    @ModifiedOn DATETIME = NULL,
    @UID UNIQUEIDENTIFIER = NULL OUTPUT
AS
BEGIN
    SET NOCOUNT ON;
	SET @CreatedOn = ISNULL(@CreatedOn, GETDATE());
    SET @ModifiedOn = ISNULL(@ModifiedOn, GETDATE());

    -- Upsert logic
    IF EXISTS (SELECT 1 FROM Organizations.BillingDetailsOrderHistory WHERE Id = @Id)
    BEGIN
        -- Update existing row
        UPDATE Organizations.BillingDetailsOrderHistory
        SET 
            Organizations = @Organizations,
			OrganizationsEntityType = @OrganizationsEntityType,
            ProductOrderBasicDetail = @ProductOrderBasicDetail,
            ProductType = @ProductType,
            NumberOfEntity = @NumberOfEntity,
            NumberOfUser = @NumberOfUser,
            AppServiceProvider = @AppServiceProvider,
            OrderId = @OrderId,
            FeePerUser = @FeePerUser,
            FeePerEntity = @FeePerEntity,
            CreatedOn = @CreatedOn,
            CreatedBy = @CreatedBy,
            ModifiedBy = @ModifiedBy,
            ModifiedOn = @ModifiedOn
        WHERE Id = @Id;
    END
    ELSE
    BEGIN
        -- Insert new row
        INSERT INTO Organizations.BillingDetailsOrderHistory (
            Organizations, OrganizationsEntityType, ProductOrderBasicDetail, ProductType, NumberOfEntity, NumberOfUser, AppServiceProvider, OrderId, FeePerUser, FeePerEntity, CreatedOn, CreatedBy, ModifiedBy, ModifiedOn, UID
        )
        VALUES (
            @Organizations,@OrganizationsEntityType, @ProductOrderBasicDetail, @ProductType, @NumberOfEntity, @NumberOfUser, @AppServiceProvider, @OrderId, @FeePerUser, @FeePerEntity, @CreatedOn, @CreatedBy, @ModifiedBy, @ModifiedOn, NEWID()
        );

        -- Get the Id of the newly inserted row
        SET @Id = SCOPE_IDENTITY();
    END

    -- Return the upserted row
    SELECT * FROM Organizations.BillingDetailsOrderHistory WHERE Id = @Id;
END
GO
