CREATE PROCEDURE [product_owner].[USP_GET_REGULATION_SETUP_APPROVAL_LIST] -- '16193229-D8DC-4B89-8209-4E2FADE34930'
	(
		@UserUID NVARCHAR(100)
		
	)
AS
BEGIN
	

	DECLARE @UserId INT;

	
	SELECT @UserId = ID FROM Users WHERE UID=@UserUID

	
	SELECT CSM.HistoryId, CSA.Id,UK.FullName,'Regulation Setup' as RegulationType,
	CSA.ApprovalStatus AS StatusId,RAS.Status,CSA.UID as ApproverUID,CSA.CreatedBy,U.FullName AS ApprovedBy,
	CSM.RegulationName AS DisplayName, CSA.CreatedOn
	FROM [product_owner].RegulationSetupApproval CSA
	INNER JOIN [product_owner].RegulationSetupHistory CSM ON CSM.HistoryId = CSA.HistoryId
	INNER JOIN [dbo].Users U ON U.Id = CSA.ManagerId
	INNER JOIN [dbo].Users UK ON UK.Id = CSA.CreatedBy
	INNER JOIN [dbo].RefApprovalStatus RAS ON RAS.Id = CSA.ApprovalStatus
	WHERE CSA.ManagerId=@UserId OR CSA.CreatedBy = @UserId

	UNION ALL


	SELECT CSM.HistoryId, CSA.Id,UK.FullName,'Regulation Compliance' as RegulationType,
	CSA.ApprovalStatus AS StatusId,RAS.Status,CSA.UID as ApproverUID,CSA.CreatedBy,U.FullName AS ApprovedBy,
	CSM.ComplianceName AS DisplayName, CSA.CreatedOn
	FROM [product_owner].RegulationSetupComplianceApproval CSA
	INNER JOIN [product_owner].RegulationSetupComplianceHistory CSM ON CSM.HistoryId = CSA.HistoryId
	INNER JOIN [dbo].Users U ON U.Id = CSA.ManagerId
	INNER JOIN [dbo].Users UK ON UK.Id = CSA.CreatedBy
	INNER JOIN [dbo].RefApprovalStatus RAS ON RAS.Id = CSA.ApprovalStatus
	WHERE CSA.ManagerId=@UserId OR CSA.CreatedBy = @UserId

	UNION ALL

	SELECT CSM.HistoryId, CSA.Id,UK.FullName,csa.TOCRuleType as RegulationType,
	CSA.ApprovalStatus AS StatusId,RAS.Status,CSA.UID as ApproverUID,CSA.CreatedBy,U.FullName AS ApprovedBy,
	RC.ComplianceName AS DisplayName, CSA.CreatedOn
	FROM [product_owner].TOCApproval CSA
	INNER JOIN [product_owner].TOCHistory CSM ON CSM.HistoryId = CSA.HistoryId
	LEFT JOIN [product_owner].RegulationSetupCompliance RC  ON RC.ID = CSM.COMPLIANCEID
	LEFT JOIN [product_owner].RegulationSetupDetails RS  ON RC.ID = CSM.RegulationSetupId
	INNER JOIN [dbo].Users U ON U.Id = CSA.ManagerId
	INNER JOIN [dbo].Users UK ON UK.Id = CSA.CreatedBy
	INNER JOIN [dbo].RefApprovalStatus RAS ON RAS.Id = CSA.ApprovalStatus
	WHERE CSA.ManagerId=@UserId OR CSA.CreatedBy = @UserId

	ORDER BY 
    CreatedOn DESC;
END
GO
