CREATE PROCEDURE [product_owner].[USP_POSTCOUNTRYSTATEMAPPING] 
	(
		@Id						INT = 0,
		@CountryId			    INT = 0,
		@StateId			    INT = 0,
		@CreatedBy				INT = 0,
		@UID					NVARCHAR(100) = NULL
	)
AS
BEGIN
	DECLARE @FROMDATE DATETIME, @TODATE DATETIME;

	IF(@Id = 0 or @Id is null)
	BEGIN
		IF NOT EXISTS(SELECT * FROM [product_owner].[CountryStateMapping] WHERE CountryID=@CountryId AND StateID =@StateId AND Status = 1)
		BEGIN
			SELECT TOP 1 @FROMDATE =FinancialStartDate, @TODATE = FinancialEndDate  FROM [product_owner].Country WHERE ID = @CountryId
			INSERT INTO [product_owner].[CountryStateMapping](CountryID,StateID,CreatedOn,CreatedBy,Status,FinancialStartDate,FinancialEndDate)
			VALUES(@CountryId,@StateId,GETDATE(),@CreatedBy,0,@FROMDATE,@TODATE);

			SELECT @Id = SCOPE_IDENTITY() 
		END;
		ELSE
		BEGIN
			SELECT @Id=Id FROM [product_owner].[CountryStateMapping] WHERE CountryID=@CountryId AND StateID =@StateId
		  	SELECT 
				  SM.Id,
				  SM.CountryId,
				  SM.StateId,
				  SM.Status,
				  SM.UID,
				  C.CountryName,
				  S.StateName,
				  C.CountryCode,
				  S.StateCode
			, 0 AS ResponseCode,'Country '+c.CountryName + ' State '+ S.StateName + ' already exists' AS ResponseMessage FROM
			[product_owner].[CountryStateMapping] SM
			INNER JOIN [PRODUCT_OWNER].[COUNTRY] C ON C.ID = SM.COUNTRYID
			INNER JOIN [PRODUCT_OWNER].[STATE] S ON S.ID = SM.STATEID
			WHERE SM.Id =@Id
			return
		END;
	END;
	ELSE
	BEGIN
		UPDATE [product_owner].[CountryStateMapping] SET
		CountryID = @CountryId,
		StateID =@StateId,
		ModifiedBy = @CreatedBy,
		ModifiedOn = GETDATE(),
		Status = 0
		WHERE UID = @UID
	END;

	SELECT 
          SM.Id,
		  SM.CountryId,
		  SM.StateId,
		  SM.Status,
		  SM.UID,
		  C.CountryName,
		  S.StateName,
		  C.CountryCode,
		  S.StateCode
	, 1 AS ResponseCode,'Successfully saved and sent for review' AS ResponseMessage FROM
	[product_owner].[CountryStateMapping] SM
	INNER JOIN [PRODUCT_OWNER].[COUNTRY] C ON C.ID = SM.COUNTRYID
	INNER JOIN [PRODUCT_OWNER].[STATE] S ON S.ID = SM.STATEID
	WHERE SM.Id =@Id
	
END;


